func (srv *Server) serveUDP(l *net.UDPConn) error {
	defer l.Close()
	handler := srv.Handler
	if handler == nil {
		handler = DefaultServeMux
	}
	if srv.UDPSize == 0 {
		srv.UDPSize = MinMsgSize
	}
	rtimeout := dnsTimeout
	if srv.ReadTimeout != 0 {
		rtimeout = srv.ReadTimeout
	}
	for {
		m, a, e := srv.readUDP(l, rtimeout)
		if e != nil {
			continue
		}
		go srv.serve(a, handler, m, l, nil)
